Q: VS code Format Code command and shortcut Shift+Alt+F doesn&#39;t work A: <p>python -m black {source_file_or_directory}</p>
<p>python -m black .</p>
<pre><code>from pathlib import Path
import shutil
import re

PASTA_PROJETO = Path(&quot;gerarScriptdeVideo&quot;)
BACKUP = Path(&quot;gerarScriptdeVideo_backup&quot;)

BLOCO_INICIA = (
    &quot;class &quot;,
    &quot;def &quot;,
    &quot;async def &quot;,
    &quot;if &quot;,
    &quot;elif &quot;,
    &quot;else:&quot;,
    &quot;for &quot;,
    &quot;while &quot;,
    &quot;try:&quot;,
    &quot;except&quot;,
    &quot;finally:&quot;,
    &quot;with &quot;,
    &quot;async with &quot;,
)


def eh_linha_bloco(txt):
    txt = txt.strip()
    return txt.endswith(&quot;:&quot;) and any(txt.startswith(x) for x in BLOCO_INICIA)


def eh_decorator(txt):
    return txt.strip().startswith(&quot;@&quot;)


def eh_import(txt):
    txt = txt.strip()
    return txt.startswith(&quot;import &quot;) or txt.startswith(&quot;from &quot;)


def eh_atributo_classe(txt):
    txt = txt.strip()

    if not txt:
        return False

    if txt.startswith(&quot;#&quot;):
        return False

    if txt.startswith((&quot;def &quot;, &quot;class &quot;, &quot;@&quot;)):
        return False

    if &quot;=&quot; in txt:
        return True

    if &quot;:&quot; in txt:
        return True

    return False


def reconstruir_python(texto):
    linhas = texto.splitlines()

    saida = []

    nivel = 0
    dentro_classe = False
    dentro_funcao = False

    for linha in linhas:

        bruto = linha.rstrip()
        txt = bruto.strip()

        if not txt:
            saida.append(&quot;&quot;)
            continue

        if eh_import(txt):
            nivel = 0
            dentro_funcao = False
            saida.append(txt)
            continue

        if eh_decorator(txt):
            saida.append(&quot;    &quot; * nivel + txt)
            continue

        if txt.startswith(&quot;class &quot;):
            nivel = 0
            dentro_classe = True
            dentro_funcao = False
            saida.append(txt)
            nivel = 1
            continue

        if txt.startswith((&quot;def &quot;, &quot;async def &quot;)):
            if dentro_classe:
                saida.append(&quot;    &quot; + txt)
                nivel = 2
            else:
                saida.append(txt)
                nivel = 1

            dentro_funcao = True
            continue

        if dentro_classe and not dentro_funcao:

            if eh_atributo_classe(txt):
                saida.append(&quot;    &quot; + txt)
                continue

        if txt.startswith((&quot;elif &quot;, &quot;else:&quot;, &quot;except&quot;, &quot;finally:&quot;)):
            nivel = max(1, nivel - 1)

        saida.append(&quot;    &quot; * nivel + txt)

        if eh_linha_bloco(txt):
            nivel += 1

        if txt.startswith((&quot;return&quot;, &quot;break&quot;, &quot;continue&quot;, &quot;pass&quot;)):
            nivel = max(1, nivel - 1)

    return &quot;\n&quot;.join(saida) + &quot;\n&quot;


def processar_arquivo(arq):

    original = arq.read_text(encoding=&quot;utf-8&quot;, errors=&quot;ignore&quot;)

    novo = reconstruir_python(original)

    arq.write_text(novo, encoding=&quot;utf-8&quot;)


def main():

    if not PASTA_PROJETO.exists():
        print(&quot;Pasta não encontrada.&quot;)
        return

    if BACKUP.exists():
        shutil.rmtree(BACKUP)

    shutil.copytree(PASTA_PROJETO, BACKUP)

    total = 0

    for arq in PASTA_PROJETO.rglob(&quot;*.py&quot;):

        try:
            processar_arquivo(arq)
            total += 1
            print(f&quot;OK: {arq}&quot;)

        except Exception as e:
            print(f&quot;ERRO: {arq}&quot;)
            print(e)

    print()
    print(f&quot;Arquivos processados: {total}&quot;)
    print(f&quot;Backup salvo em: {BACKUP}&quot;)


if __name__ == &quot;__main__&quot;:
    main()


--------------------------------------------------------------------------
</code></pre>
<pre><code>from pathlib import Path
import shutil
import re

PROJECT_FOLDER = Path(&quot;sourcedir&quot;)
BACKUP = Path(&quot;sourcedir_backup&quot;)

BLOCK_STARTS = (
    &quot;class &quot;,
    &quot;def &quot;,
    &quot;async def &quot;,
    &quot;if &quot;,
    &quot;elif &quot;,
    &quot;else:&quot;,
    &quot;for &quot;,
    &quot;while &quot;,
    &quot;try:&quot;,
    &quot;except&quot;,
    &quot;finally:&quot;,
    &quot;with &quot;,
    &quot;async with &quot;,
)


def is_block_line(txt):
    txt = txt.strip()
    return txt.endswith(&quot;:&quot;) and any(txt.startswith(x) for x in BLOCK_STARTS)


def is_decorator(txt):
    return txt.strip().startswith(&quot;@&quot;)


def is_import(txt):
    txt = txt.strip()
    return txt.startswith(&quot;import &quot;) or txt.startswith(&quot;from &quot;)


def is_class_attribute(txt):
    txt = txt.strip()

    if not txt:
        return False

    if txt.startswith(&quot;#&quot;):
        return False

    if txt.startswith((&quot;def &quot;, &quot;class &quot;, &quot;@&quot;)):
        return False

    if &quot;=&quot; in txt:
        return True

    if &quot;:&quot; in txt:
        return True

    return False


def rebuild_python(text):
    lines = text.splitlines()

    output = []

    level = 0
    inside_class = False
    inside_function = False

    for line in lines:

        raw = line.rstrip()
        txt = raw.strip()

        if not txt:
            output.append(&quot;&quot;)
            continue

        if is_import(txt):
            level = 0
            inside_function = False
            output.append(txt)
            continue

        if is_decorator(txt):
            output.append(&quot;    &quot; * level + txt)
            continue

        if txt.startswith(&quot;class &quot;):
            level = 0
            inside_class = True
            inside_function = False
            output.append(txt)
            level = 1
            continue

        if txt.startswith((&quot;def &quot;, &quot;async def &quot;)):
            if inside_class:
                output.append(&quot;    &quot; + txt)
                level = 2
            else:
                output.append(txt)
                level = 1

            inside_function = True
            continue

        if inside_class and not inside_function:

            if is_class_attribute(txt):
                output.append(&quot;    &quot; + txt)
                continue

        if txt.startswith((&quot;elif &quot;, &quot;else:&quot;, &quot;except&quot;, &quot;finally:&quot;)):
            level = max(1, level - 1)

        output.append(&quot;    &quot; * level + txt)

        if is_block_line(txt):
            level += 1

        if txt.startswith((&quot;return&quot;, &quot;break&quot;, &quot;continue&quot;, &quot;pass&quot;)):
            level = max(1, level - 1)

    return &quot;\n&quot;.join(output) + &quot;\n&quot;


def process_file(file):

    original = file.read_text(encoding=&quot;utf-8&quot;, errors=&quot;ignore&quot;)

    new = rebuild_python(original)

    file.write_text(new, encoding=&quot;utf-8&quot;)


def main():

    if not PROJECT_FOLDER.exists():
        print(&quot;Folder not found.&quot;)
        return

    if BACKUP.exists():
        shutil.rmtree(BACKUP)

    shutil.copytree(PROJECT_FOLDER, BACKUP)

    total = 0

    for file in PROJECT_FOLDER.rglob(&quot;*.py&quot;):

        try:
            process_file(file)
            total += 1
            print(f&quot;OK: {file}&quot;)

        except Exception as e:
            print(f&quot;ERROR: {file}&quot;)
            print(e)

    print()
    print(f&quot;Files processed: {total}&quot;)
    print(f&quot;Backup saved to: {BACKUP}&quot;)


if __name__ == &quot;__main__&quot;:
    main()
</code></pre>

Q: Codeigniter pass db result object from model to controller A: <p>Model methods should not directly access submission or session data. Instead pass in the username value as a parameter of the model method and return either <code>null</code> if there is no qualifying account or the id of the qualifying account.</p>
<p>Model:</p>
<pre class="lang-php prettyprint-override"><code>public function getIdFromUsername(string $username): ?int
{
    return $this-&gt;db-&gt;get_where('membership', ['username' =&gt; $username], 1)-&gt;row('id');
}
</code></pre>
<p>Controller:</p>
<pre class="lang-php prettyprint-override"><code>public function setUsernameSession()
{

    $this-&gt;load-&gt;model('membership_model', 'MembershipModel');

    if (
        ($username = $this-&gt;input-&gt;post('username'))
        &amp;&amp; ($userId = $this-&gt;MembershipModel-&gt;getUser_id($username))
    ) {
        $this-&gt;session-&gt;set_userdata([
            'session_id' =&gt; $str = do_hash($str),
            'user_id' =&gt; $userId,
            'username' =&gt; $username,
            'is_logged_in' =&gt; true
        ]);
    }
    redirect('site/members_area');
}
</code></pre>

Q: Is it possible to make the transition from 270deg to 360deg be to 0deg without rotating counter clockwise? A: <p>Keep adding 90 deg on each inner element click. You must not reset to a <em>lower</em> than the current value at this point, otherwise it will reverse direction.</p>
<p>To reset, rotate back to the highest multiple of 360 than fits into the current value - <code>deg -= deg % 360;</code></p>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false" data-babel-preset-react="false" data-babel-preset-ts="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>"use strict;"
let
   deg = 0,
   outer = document.body.firstElementChild,
   inner = outer.firstElementChild,
   reset = outer.nextElementSibling
;
inner.addEventListener(
  'mousedown',
  (evt) =&gt; { 
        deg += 90;
        outer.style.setProperty('--rotdeg',`${deg}deg`);
  }
);
reset.addEventListener(
   'mousedown',
   () =&gt; {
      deg -= deg % 360;
      outer.style.setProperty('--rotdeg',`${deg}deg`);
   }
);</code></pre>
<pre class="snippet-code-css lang-css prettyprint-override"><code>.outer {
  width: fit-content;
  border: 1px solid black;
  --rotdeg: 0;
}
.inner {
  height: 100px;
  width:100px;
  line-height:100px;
  text-align:center;
  background-color:rgb(200,200,200);
  transform: rotate(var(--rotdeg));
  transition-duration: 300ms;
  transition-property: transform;
  transition-timing-function: ease-in-out;
}</code></pre>
